return{x:e.clientX-r.left,y:e.clientY-r.top}};canvas.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;ink=true;const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drawing)return;const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke()});canvas.addEventListener('pointerup',()=>{drawing=false;if(ink)hidden.value=canvas.toDataURL('image/png')});wrap.querySelector(`[data-clear-signature="${key}"]`).addEventListener('click',()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ink=false;hidden.value=''})});form.addEventListener('submit',e=>{if([...form.querySelectorAll('[data-signature-value]')].some(i=>!i.value)){e.preventDefault();alert('Faça as duas assinaturas antes de gerar o romaneio.')}})}
