<script>
(()=>{const form=document.querySelector('.romaneio-form');if(!form)return;form.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();if(form.dataset.liveSubmitting==='1')return;const signatures=[...form.querySelectorAll('[data-signature-value]')];if(signatures.some(input=>!input.value)){window.showAppToast?.('Faça as duas assinaturas antes de gerar o romaneio.','error');return}const pedidoId=String(form.elements.pedido_id?.value||'');const submit=form.querySelector('[type="submit"]');form.dataset.liveSubmitting='1';if(submit){submit.disabled=true;submit.setAttribute('aria-busy','true')}try{const response=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível registrar a expedição.');form.reset();signatures.forEach(input=>input.value='');form.querySelectorAll('[data-signature]').forEach(canvas=>canvas.getContext('2d')?.clearRect(0,0,canvas.width,canvas.height));if(form.elements.pedido_id)form.elements.pedido_id.value='';if(form.elements.volumes)form.elements.volumes.value='1';if(form.elements.peso_total)form.elements.peso_total.value='0';if(form.elements.transportadora)form.elements.transportadora.value='';if(form.elements.motorista_nome)form.elements.motorista_nome.value='';const option=form.querySelector(`select[name="pedido_id"] option[value="${CSS.escape(pedidoId)}"]`);option?.remove();const selectButton=document.querySelector(`[data-select-expedition="${CSS.escape(pedidoId)}"]`);selectButton?.closest('tr')?.remove();const romaneioCount=document.querySelector('[data-tab-target="romaneio"] .expedicao-count'),concluidosCount=document.querySelector('[data-tab-target="concluidos"] .expedicao-count');if(romaneioCount)romaneioCount.textContent=String(Math.max(0,Number(romaneioCount.textContent||0)-1));if(concluidosCount)concluidosCount.textContent=String(Number(concluidosCount.textContent||0)+1);const tbody=document.querySelector('[data-tab-panel="romaneio"] tbody');if(tbody&&!tbody.querySelector('[data-select-expedition]'))tbody.innerHTML='<tr><td colspan="5" class="expedicao-empty">Nenhum pedido em separação disponível.</td></tr>';window.showAppToast?.('Expedição registrada e formulário limpo.','success');form.elements.pedido_id?.focus()}catch(error){window.showAppToast?.(error.message||'Não foi possível registrar a expedição.','error')}finally{delete form.dataset.liveSubmitting;if(submit){submit.disabled=false;submit.removeAttribute('aria-busy')}}},true)})();
