<script>
(()=>{const params=new URLSearchParams(location.search),form=document.querySelector('.romaneio-form');if(params.get('expedicao_registrada')==='1'&&form){form.reset();form.querySelectorAll('[data-signature-value]').forEach(input=>input.value='');form.querySelectorAll('[data-signature]').forEach(canvas=>canvas.getContext('2d')?.clearRect(0,0,canvas.width,canvas.height));history.replaceState({},'',location.pathname+'?tab=concluidos')}const ajustar=()=>document.querySelectorAll('[data-signature]').forEach(canvas=>{const rect=canvas.getBoundingClientRect();if(rect.width<20||rect.height<20)return;const ratio=window.devicePixelRatio||1,w=Math.round(rect.width*ratio),h=Math.round(rect.height*ratio);if(canvas.width===w&&canvas.height===h)return;canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round'});document.querySelector('[data-tab-target="romaneio"]')?.addEventListener('click',()=>requestAnimationFrame(()=>requestAnimationFrame(ajustar)));window.addEventListener('resize',ajustar);new ResizeObserver(ajustar).observe(document.querySelector('[data-tab-panel="romaneio"]')||document.body);if(params.get('tab')==='romaneio')requestAnimationFrame(()=>requestAnimationFrame(ajustar))})();
