<script>
(()=>{const mobile=()=>window.matchMedia('(max-width:700px)').matches;document.querySelectorAll('.signature-box').forEach(box=>{const canvas=box.querySelector('[data-signature]'),key=canvas?.dataset.signature,hidden=box.closest('label')?.querySelector(`[data-signature-value="${key}"]`);if(!canvas||!hidden)return;const done=document.createElement('button');done.type='button';done.className='signature-mobile-done';done.textContent='Concluir';box.appendChild(done);const redraw=()=>{const source=hidden.value;if(!source)return;const image=new Image();image.onload=()=>{const rect=canvas.getBoundingClientRect(),ctx=canvas.getContext('2d'),ratio=window.devicePixelRatio||1;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,10*ratio,10*ratio,Math.max(1,canvas.width-20*ratio),Math.max(1,canvas.height-20*ratio))};image.src=source};canvas.addEventListener('pointerdown',event=>{if(!mobile()||box.classList.contains('is-mobile-expanded'))return;event.preventDefault();event.stopImmediatePropagation();document.querySelectorAll('.signature-box.is-mobile-expanded').forEach(open=>open.classList.remove('is-mobile-expanded'));box.classList.add('is-mobile-expanded');document.body.classList.add('signature-mobile-open');window.dispatchEvent(new Event('resize'));setTimeout(redraw,80)},true);done.addEventListener('click',()=>{box.classList.remove('is-mobile-expanded');document.body.classList.remove('signature-mobile-open');window.dispatchEvent(new Event('resize'));setTimeout(redraw,80)})});window.addEventListener('keydown',event=>{if(event.key!=='Escape')return;document.querySelectorAll('.signature-box.is-mobile-expanded').forEach(box=>box.querySelector('.signature-mobile-done')?.click())})})();
</script>
<script>
(()=>{const isMobile=()=>window.matchMedia('(max-width:700px)').matches;const unlock=()=>{try{screen.orientation?.unlock?.()}catch(error){}};document.querySelectorAll('.signature-box').forEach(box=>{const canvas=box.querySelector('[data-signature]'),done=box.querySelector('.signature-mobile-done');box.addEventListener('pointerdown',async event=>{if(event.target!==canvas||!isMobile()||document.fullscreenElement)return;try{await box.requestFullscreen?.({navigationUI:'hide'});await screen.orientation?.lock?.('landscape')}catch(error){box.dataset.orientationFallback='1'}},true);done?.addEventListener('click',async()=>{unlock();if(document.fullscreenElement===box){try{await document.exitFullscreen()}catch(error){}}})});document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement)return;unlock();document.querySelectorAll('.signature-box.is-mobile-expanded').forEach(box=>box.querySelector('.signature-mobile-done')?.click())})})();
</script>
<script>
(()=>{document.querySelectorAll('.signature-box').forEach(box=>{const canvas=box.querySelector('[data-signature]'),key=canvas?.dataset.signature,hidden=box.closest('label')?.querySelector(`[data-signature-value="${key}"]`),done=box.querySelector('.signature-mobile-done');if(!canvas||!hidden)return;const persist=()=>{try{const pixels=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data;let hasInk=false;for(let index=3;index<pixels.length;index+=16){if(pixels[index]>0){hasInk=true;break}}if(hasInk)hidden.value=canvas.toDataURL('image/png')}catch(error){}};canvas.addEventListener('pointerup',persist,true);canvas.addEventListener('pointercancel',persist,true);done?.addEventListener('click',persist,true)})})();
</script>
<script>
(()=>{const restore=(canvas,hidden)=>{if(!hidden.value)return;const image=new Image();image.onload=()=>{const ctx=canvas.getContext('2d'),ratio=window.devicePixelRatio||1,targetWidth=canvas.width,targetHeight=canvas.height;if(targetWidth<2||targetHeight<2)return;const scale=Math.min((targetWidth-20*ratio)/image.width,(targetHeight-20*ratio)/image.height),width=Math.max(1,image.width*scale),height=Math.max(1,image.height*scale),x=(targetWidth-width)/2,y=(targetHeight-height)/2;ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,targetWidth,targetHeight);ctx.drawImage(image,x,y,width,height);ctx.restore();ctx.setTransform(ratio,0,0,ratio,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round'};image.src=hidden.value};const schedule=(canvas,hidden)=>[80,180,360,650].forEach(delay=>setTimeout(()=>restore(canvas,hidden),delay));document.querySelectorAll('.signature-box').forEach(box=>{const canvas=box.querySelector('[data-signature]'),key=canvas?.dataset.signature,hidden=box.closest('label')?.querySelector(`[data-signature-value="${key}"]`),done=box.querySelector('.signature-mobile-done');if(!canvas||!hidden)return;done?.addEventListener('click',()=>schedule(canvas,hidden));new ResizeObserver(()=>{if(!box.classList.contains('is-mobile-expanded')&&hidden.value)schedule(canvas,hidden)}).observe(box)});document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement)return;document.querySelectorAll('.signature-box').forEach(box=>{const canvas=box.querySelector('[data-signature]'),key=canvas?.dataset.signature,hidden=box.closest('label')?.querySelector(`[data-signature-value="${key}"]`);if(canvas&&hidden)schedule(canvas,hidden)})})})();
</script>
